"""Catatan belajar untuk runtime MLP commit 15bc7bb; tidak berisi data siswa."""

GLOSSARY = {
 'checkpoint': ('Alamat model dan bobot tersimpan', 'Dalam ROBERTA_CHECKPOINT, checkpoint adalah alamat model pretrained di Hugging Face. File final.pt adalah checkpoint hasil latihan. Keduanya berbeda dari objek model di RAM.'),
 'token': ('Potongan teks', 'Token adalah unit yang dibaca tokenizer. Satu kata bisa menjadi beberapa token. ID token adalah nomor kosakata, bukan nilai kata atau skor esai.'),
 'tokenizer': ('Penerjemah teks menjadi token', 'AutoTokenizer memuat tokenizer milik checkpoint yang dipilih. RoBERTa dan BGE-M3 punya kosakata dan pemotongan sendiri; jumlah atau ID token keduanya tidak langsung sebanding.'),
 'embedding': ('Vektor sebagai fitur teks', 'Satu vektor berisi banyak angka yang dipelajari model untuk merepresentasikan teks. Koordinat bukan skor, probabilitas, atau label rubrik. Makna muncul dari pola bersama antarkoordinat.'),
 'CLS': ('Ringkasan pada token pertama', 'Kode mengambil last_hidden_state[:, 0, :]: semua window, token pertama, semua koordinat. Token pertama menjadi representasi ringkas window. RoBERTa menggabungkan beberapa window dengan rata-rata.'),
 'window': ('Potongan jawaban panjang', 'RoBERTa dibatasi 512 token termasuk special token. Isi dibagi menjadi window yang tumpang tindih agar semua token isi tercakup. Mapping menjaga hubungan window dengan jawaban asal.'),
 'special': ('Penanda awal dan akhir', 'Untuk satu teks RoBERTa, <s> dan </s> memakai dua posisi. Kapasitas 512 menjadi 510 token isi + 2 special. Token special ditambahkan sekali untuk setiap window.'),
 'fine-tuned': ('Encoder ikut belajar dari skor guru', 'requires_grad=True membuat parameter encoder dapat menerima gradien. Optimizer harus memasukkan parameter itu agar bobotnya benar-benar diperbarui. Di file MLP ini, RoBERTa S1 dan S3 ikut dilatih.'),
 'frozen': ('Bobot encoder tetap', 'Parameter encoder tidak diperbarui oleh latihan head. BGE-M3 menghasilkan fitur tetap yang dipakai bersama S2/S3. Proyeksi atau MLP sesudah fitur tersebut tetap boleh belajar.'),
 'head': ('Lapisan pembuat prediksi', 'Head menerima fitur encoder lalu menghasilkan skor. Head S1 linear 768→1. Head S2 dan S3 adalah MLP 1024→256→1. Semua menghasilkan satu skor kontinu.'),
 'MLP': ('Jaringan lapisan linear dan aktivasi', 'MLP di sini: Linear(1024,256) → GELU → Dropout → Linear(256,1). Lapisan tersembunyi memberi keluwesan hubungan fitur-skor. Lebih fleksibel tidak menjamin RMSE lebih kecil.'),
 'GELU': ('Aktivasi nonlinier', 'GELU mengubah keluaran linear secara nonlinier. Tanpa aktivasi nonlinier, menumpuk beberapa lapisan linear tetap setara dengan satu pemetaan linear.'),
 'LayerNorm': ('Normalisasi di dalam satu vektor', 'LayerNorm menata skala koordinat pada setiap contoh, dengan skala dan bias yang dapat dilatih. Tambahan LayerNorm RoBERTa pada S3 berbeda dari LayerNorm yang memang sudah ada di encoder.'),
 'L2': ('Normalisasi panjang vektor', 'functional.normalize(...,dim=1) membagi vektor dengan normanya sehingga panjang L2 mendekati satu. Ini berbeda dari LayerNorm. Nilai komponen tetap dapat negatif.'),
 'projection': ('Pemadatan fitur yang belajar', 'Cabang BGE S3 dipetakan dari 1024 ke 256 angka dengan Linear lalu LayerNorm. Encoder BGE frozen, tetapi parameter proyeksi ini ikut dilatih.'),
 'concat': ('Menyambung dua vektor', 'torch.cat(...,dim=1) menyambungkan fitur sepanjang kolom. S3 memakai 768 RoBERTa setelah LayerNorm + 256 proyeksi BGE = 1024. Ini bukan menjumlahkan atau merata-ratakan kedua encoder.'),
 'dropout': ('Mematikan sebagian aktivasi saat latihan', 'Dropout menjadi regularisasi saat model.train(). Saat model.eval(), dropout dimatikan. Maka fitur dropout_eval di Excel sama dengan masukan dropout saat mode prediksi.'),
 'batch': ('Kelompok jawaban untuk pembaruan', 'Microbatch 1 berarti satu jawaban diproses sekaligus. Gradien dikumpulkan hingga batch efektif 8 jawaban, baru optimizer memperbarui bobot. Jadi notebook ini tetap menggunakan batch.'),
 'epoch': ('Satu lintasan data latih tahap itu', 'Satu epoch membaca semua contoh training pada fold/refit yang sedang aktif. Lima fold × lima epoch tidak berarti satu model yang sama mendapat 25 epoch; setiap fold memulai model baru.'),
 'learning rate': ('Ukuran langkah pembaruan bobot', 'Angka ini pengaturan optimizer, bukan skor akurasi. Encoder RoBERTa memakai 1e-5; proyeksi/head memakai 1e-4 pada run ini. Kualitasnya dinilai dari validation, bukan dari besar angkanya sendiri.'),
 'loss': ('Kesalahan yang dipakai untuk belajar', 'Loss MSE dihitung saat training dengan target 0–1. backward menghitung gradien dan optimizer.step memperbarui parameter untuk berusaha memperkecil loss.'),
 'MSE': ('Rata-rata selisih kuadrat', 'MSE = mean((guru − prediksi)²). Di log latihan, target telah dinormalisasi ke 0–1. MSE tidak mempunyai batas universal bahwa 1 adalah nilai paling buruk.'),
 'RMSE': ('Kesalahan dalam satuan poin skor', 'RMSE = sqrt(mean((guru − prediksi)²)). Notebook mengembalikan prediksi ke 0–100 dahulu. RMSE 6 berarti ukuran kesalahan sekitar enam poin menurut rumus ini, bukan 6% akurasi atau selisih persis setiap jawaban.'),
 'Pearson': ('Hubungan perubahan dua skor', 'Pearson mengukur apakah skor prediksi naik/turun bersama skor guru. Korelasi tinggi tetap dapat muncul ketika semua prediksi bergeser dari skor guru. Periksa RMSE dan agreement juga.'),
 'QWK': ('Kesepakatan kategori dengan bobot kuadratik', 'QWK membandingkan kategori guru dan salinan prediksi yang dibulatkan, memberi penalti lebih besar untuk jarak kategori yang lebih jauh, lalu mengoreksi kesepakatan karena peluang.'),
 'AC2': ('Gwet AC2 kuadratik', 'AC2 juga menilai agreement berbobot, tetapi koreksi peluangnya berbeda dari QWK. AC2 0,98 bukan berarti 98% prediksi tepat. Skala kategori 0–100 dan bobot kuadratik dapat membuat kesalahan beberapa poin mendapat bobot agreement tinggi.'),
 'cross-validation': ('Validasi bergantian di development', '240 jawaban development dibagi lima fold berbasis kelompok. Sekitar 192 digunakan melatih dan 48 memvalidasi pada setiap putaran. Ini sudah bentuk validasi; 60 test tetap dipisahkan untuk evaluasi akhir.'),
 'leakage': ('Informasi penilaian bocor ke proses pemilihan', 'Email, skor guru, soal dan kunci bukan fitur encoder dalam pipeline ini. Kelompok email/duplikat dijaga tidak menyeberang split. Test tidak dipakai memilih epoch atau pengaturan.'),
 'early stopping': ('Berhenti saat hasil validasi tidak membaik', 'Patience 5 menghitung epoch berturut-turut yang tidak mengalahkan RMSE validasi terbaik sebelumnya. RMSE turun dari epoch terakhir belum tentu mengalahkan rekor terbaik.'),
 'refit': ('Melatih model final setelah CV', 'Sesudah semua CV selesai, jumlah epoch final dipilih dari ceil(median(epoch terbaik lima fold)). Model baru dilatih pada seluruh 240 development. Kembali ke S1 setelah CV S3 adalah tahap refit, bukan output kosong.'),
 'gradient': ('Arah perubahan parameter', 'backward menghitung pengaruh parameter terhadap loss. Optimizer menggunakan gradien untuk memperbarui bobot. no_grad hanya mematikan pencatatan gradien di blok pembacaan, tidak menghapus kemampuan model untuk dilatih nanti.'),
 'tensor': ('Larik angka dengan bentuk tertentu', 'Contoh [N,768] berarti N jawaban dan 768 koordinat per jawaban. [N,1] adalah satu prediksi untuk tiap jawaban. Shape diperiksa agar perhitungan tidak salah karena broadcasting.'),
 'revision': ('Versi bobot/tokenizer yang dikunci', 'Revision SHA menjaga pengunduhan model memakai versi yang sama. Ini berbeda dari commit GitHub kode eksperimen, dan berbeda lagi dari checkpoint hasil training.'),
 'contextual': ('Vektor yang mempertimbangkan konteks', 'Lookup embedding awal dipilih dari ID token. Setelah melewati Transformer, vektor dipengaruhi token lain dan posisi. Kata sama tidak wajib mempunyai vektor contextual yang sama.'),
 'cosine': ('Kemiripan arah vektor', 'Cosine membandingkan arah dua vektor. Mendekati satu berarti arah mirip, tetapi belum membuktikan semua komponennya identik. Tabel juga memeriksa selisih komponen dan toleransi numerik.'),
 'normalisasi skor': ('Mengubah satuan target untuk latihan', 'Skor guru 0–100 diubah ke 0–1 untuk loss, lalu prediksi dikembalikan ke skala 0–100. Normalisasi target bukan pembulatan kategori dan bukan LayerNorm fitur.'),
}

def chapter(slug, title, cells, goal, flow, read, terms, book=None, sheets=()):
    return dict(slug=slug,title=title,cells=cells,goal=goal,flow=flow,read=read,terms=terms,book=book,sheets=list(sheets))

