 (30,'self.roberta_norm =', 'LayerNorm tambahan RoBERTa','Menata 768 komponen sebelum digabung dengan cabang BGE. Layer ini berada di luar encoder dan khusus S3.', 'LayerNorm'),
 (30,'self.projection =', 'Cabang BGE dipadatkan','1024 fitur BGE menjadi 256. Encoder BGE tetap frozen; bobot proyeksi ini ikut belajar.', 'projection'),
