 (36,"if row['validation']['RMSE'] < best_rmse:", 'Bandingkan dengan rekor terbaik','Penurunan dari epoch terakhir belum cukup; nilainya harus mengalahkan minimum validation RMSE sebelumnya.', 'early stopping'),
 (36,'save_training_progress(checkpoint,', 'Simpan keadaan belajar','Checkpoint memuat model, optimizer, scheduler, riwayat dan pengacak. Karena itu resume dapat melanjutkan, bukan memulai ulang bobot.', 'checkpoint'),
